<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f766e"><title>{{ $campaign->headline }}</title><script src="https://cdn.tailwindcss.com"></script><style>.step{display:none}.step.active{display:block;animation:enter .25s ease-out}@keyframes enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}.choice.selected{border-color:#0f766e;background:#f0fdfa;box-shadow:0 0 0 3px rgba(13,148,136,.1)}.choice.selected .dot{background:#0f766e;border-color:#0f766e;box-shadow:inset 0 0 0 4px white}</style></head><body class="min-h-screen bg-[#f3fbfa] text-slate-950"><div class="min-h-screen lg:grid lg:grid-cols-[.9fr_1.1fr]"><aside class="hidden bg-teal-900 p-12 text-white lg:flex lg:flex-col lg:justify-between"><div><div class="grid h-11 w-11 place-items-center rounded-2xl bg-white text-sm font-black text-teal-800">{{ strtoupper(substr($campaign->name,0,1)) }}</div><div class="mt-24 max-w-lg"><p class="text-sm font-black uppercase tracking-[.22em] text-teal-300">{{ $campaign->name }}</p><h1 class="mt-5 text-5xl font-black leading-tight">{{ $campaign->headline }}</h1><p class="mt-6 text-lg leading-8 text-teal-100/80">{{ $campaign->description ?: 'Tell us a little about yourself. It takes about a minute.' }}</p><div class="mt-10 rounded-2xl border border-white/10 bg-white/5 p-5"><b>Quick application</b><p class="mt-1 text-sm text-teal-100/70">Six short questions. No account required.</p></div></div></div><p class="text-xs text-teal-200/60">Powered by LAMI AI</p></aside><main class="flex min-h-screen items-center justify-center px-5 py-7 sm:px-8"><div class="w-full max-w-xl"><div class="mb-6 flex items-center justify-between lg:hidden"><div class="font-black text-teal-800">{{ $campaign->name }}</div><span class="text-xs font-bold text-slate-400">Quick application</span></div><div class="mb-8"><div class="flex justify-between text-xs font-black uppercase tracking-wider text-slate-400"><span id="label">Step 1 of 6</span><span id="pct">17%</span></div><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-teal-100"><div id="bar" class="h-full rounded-full bg-teal-600 transition-all" style="width:16.66%"></div></div></div><form id="f" method="POST" action="{{ route('marketing.campaign.submit',$campaign) }}" novalidate>@csrf<input name="website" class="hidden" tabindex="-1" autocomplete="off">@foreach(['utm_source','utm_medium','utm_campaign','utm_content','utm_term'] as $u)<input type="hidden" name="{{ $u }}" value="{{ request($u) }}">@endforeach
<section class="step active" data-n="0"><span class="text-sm font-black text-teal-700">Let's start</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">What's your name?</h2><p class="mt-3 text-slate-500">Use the name you'd like us to call you.</p><input required data-req name="name" autocomplete="name" placeholder="Your full name" class="mt-8 w-full rounded-2xl border-slate-200 bg-white px-5 py-4 text-lg focus:border-teal-600 focus:ring-teal-100"></section>
<section class="step" data-n="1"><span class="text-sm font-black text-teal-700">Stay connected</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">What's your WhatsApp number?</h2><p class="mt-3 text-slate-500">We'll use WhatsApp if we need to contact you.</p><input required data-req type="tel" name="whatsapp_number" autocomplete="tel" placeholder="e.g. 08012345678" class="mt-8 w-full rounded-2xl border-slate-200 bg-white px-5 py-4 text-lg focus:border-teal-600 focus:ring-teal-100"></section>
<section class="step" data-n="2"><span class="text-sm font-black text-teal-700">Almost there</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">What's your email address?</h2><p class="mt-3 text-slate-500">We'll only use it for relevant communication.</p><input required data-req type="email" name="email" autocomplete="email" placeholder="you@example.com" class="mt-8 w-full rounded-2xl border-slate-200 bg-white px-5 py-4 text-lg focus:border-teal-600 focus:ring-teal-100"></section>
<section class="step" data-n="3"><span class="text-sm font-black text-teal-700">Your experience</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">Have you ever sold anything online?</h2><p class="mt-3 text-slate-500">There is no wrong answer.</p><div class="mt-8 grid gap-3"><button type="button" data-name="has_sold_online" data-value="1" class="choice flex items-center justify-between rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span><b class="text-lg">Yes</b><small class="mt-1 block text-slate-500">I've sold something online.</small></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button><button type="button" data-name="has_sold_online" data-value="0" class="choice flex items-center justify-between rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span><b class="text-lg">No</b><small class="mt-1 block text-slate-500">Not yet.</small></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button></div><input type="hidden" name="has_sold_online"></section>
<section class="step" data-n="4"><span class="text-sm font-black text-teal-700">Tell us more</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">What did you sell?</h2><p class="mt-3 text-slate-500">If you haven't sold yet, tell us what you'd like to sell.</p><textarea name="what_sold" rows="4" placeholder="e.g. clothes, digital products, courses, services..." class="mt-8 w-full resize-none rounded-2xl border-slate-200 bg-white px-5 py-4 text-lg focus:border-teal-600 focus:ring-teal-100"></textarea></section>
<section class="step" data-n="5"><span class="text-sm font-black text-teal-700">Final question</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">How was the sales?</h2><p class="mt-3 text-slate-500">Choose the option that best describes your experience.</p><div class="mt-8 grid gap-3"><button type="button" data-name="sales_result" data-value="very_good" class="choice flex items-center gap-4 rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span class="text-2xl">🚀</span><span class="flex-1"><b class="text-lg">Very good</b></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button><button type="button" data-name="sales_result" data-value="good" class="choice flex items-center gap-4 rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span class="text-2xl">👍</span><span class="flex-1"><b class="text-lg">Good</b></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button><button type="button" data-name="sales_result" data-value="not_good" class="choice flex items-center gap-4 rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span class="text-2xl">🌱</span><span class="flex-1"><b class="text-lg">Not good</b></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button></div><input type="hidden" name="sales_result"></section><div id="err" class="mt-4 hidden rounded-xl bg-red-50 px-4 py-3 text-sm font-bold text-red-700"></div><div class="mt-8 flex justify-between gap-3"><button type="button" id="back" class="rounded-xl px-4 py-3 font-bold text-slate-500">← Back</button><button type="button" id="next" class="rounded-xl bg-teal-700 px-6 py-3.5 font-black text-white">Next →</button><button type="submit" id="submit" class="hidden rounded-xl bg-teal-700 px-6 py-3.5 font-black text-white">Submit application</button></div></form><p class="mt-8 text-center text-xs text-slate-400">Your details are used by {{ $campaign->name }} to follow up on this campaign.</p></div></main></div><script>(()=>{let i=0,s=[...document.querySelectorAll('.step')],f=document.getElementById('f'),n=document.getElementById('next'),b=document.getElementById('back'),sub=document.getElementById('submit'),e=document.getElementById('err');function u(){s.forEach((x,j)=>x.classList.toggle('active',j===i));let p=Math.round((i+1)/6*100);document.getElementById('label').textContent=`Step ${i+1} of 6`;document.getElementById('pct').textContent=p+'%';document.getElementById('bar').style.width=p+'%';b.classList.toggle('invisible',i===0);n.classList.toggle('hidden',i===5);sub.classList.toggle('hidden',i!==5);e.classList.add('hidden')}function v(){let x=s[i].querySelector('[data-req]');if(x&&(!x.value.trim()||(x.type==='email'&&!x.checkValidity()))){e.textContent=x.type==='email'?'Please enter a valid email address.':'Please answer this question before continuing.';e.classList.remove('hidden');x.focus();return false}if(i===3&&!f.querySelector('[name=has_sold_online]').value){e.textContent='Please choose Yes or No.';e.classList.remove('hidden');return false}if(i===5&&!f.querySelector('[name=sales_result]').value){e.textContent='Please choose one option.';e.classList.remove('hidden');return false}return true}document.querySelectorAll('[data-name]').forEach(x=>x.onclick=()=>{let z=x.dataset.name;f.querySelector('[name='+z+']').value=x.dataset.value;document.querySelectorAll('[data-name='+z+']').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');e.classList.add('hidden');if(i===3){i++;u()}});n.onclick=()=>{if(v()){i++;u()}};b.onclick=()=>{if(i){i--;u()}};f.onsubmit=x=>{if(!v())x.preventDefault();else{sub.disabled=true;sub.textContent='Submitting...'}};u()})()</script></body></html>
